import{_ as t,o,c as a,a4 as p}from"./chunks/framework.DzJZdBQK.js";const h=JSON.parse('{"title":"写作课作业-091","description":"","frontmatter":{"date":"2020-10-22T19:39:15","title":"写作课作业-091","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/091.md","filePath":"posts/homework/091.md"}'),l={name:"posts/homework/091.md"};function r(s,e,c,i,n,_){return o(),a("div",null,[...e[0]||(e[0]=[p('<blockquote><p>《微信互联网平民创业》之《一切刚刚开始》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><blockquote><p>正在研究直播、正在研究直播背后「从分销时代转向直销时代」趋势的我，几乎是瞬间 感受到了一个令人激动的事实:</p><p>微信互联网商业闭环正在形成**......**</p></blockquote><blockquote><p>所谓道法自然 —— 「道理」清楚了之后「方法」才会有用。有道理有方法，剩下都是自然而然。</p></blockquote><blockquote><p>这一切，都不是我一个人做， 而是社群的人一起做，自助之后互助，自爱之后大爱......</p></blockquote><blockquote><p>别急，慢慢来，我们能一起做很多事情，能一起走很远很远……</p></blockquote><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>道法自然</p><p>写作课时说2W1H，是一样的。道理是Why，方法是How，而最终有用的就是What了。</p><p>别急，慢慢来，我们能一起做很多事情，能一起走很远很远……</p><p>只有自己做好心理建设，不掉队，就算没有脱引而出，也不至于太差，「剩者为王」。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',18)])])}const u=t(l,[["render",r]]);export{h as __pageData,u as default};
